import{_ as a,o as i,c as t,a6 as o}from"./chunks/framework.DL_pga9_.js";const h=JSON.parse('{"title":"Bytecode Module Loading","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/bytecode_module_loading.md","filePath":"design/archive/bytecode_module_loading.md","lastUpdated":1780030916000}'),l={name:"design/archive/bytecode_module_loading.md"};function d(n,e,r,c,s,m){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="bytecode-module-loading" tabindex="-1">Bytecode Module Loading <a class="header-anchor" href="#bytecode-module-loading" aria-label="Permalink to “Bytecode Module Loading”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 8. Module-system-local order: 3.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Persist and load ORGASM bytecode modules as <code>.ngo</code> artifacts that expose the same import/export contract as source modules.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li><a href="./module_artifact_typechecker">Module Artifact And Typechecker Integration</a></li><li>Stable generic and const-generic mangling from <a href="./constant_generic_parameters">Constant Generic Parameters</a></li><li><a href="./native_module_artifacts">Native Module Artifacts</a>, for native import fallback</li></ul><p>Unblocks:</p><ul><li>Shipping precompiled standard library artifacts.</li><li><a href="./stdlib_modularization">Standard Library Modularization</a> bytecode-first mode.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li><code>.ngo</code> binary format.</li><li>Bytecode artifact read/write.</li><li>Export/import metadata persistence.</li><li>ABI and metadata version checks.</li><li>ORGASM VM import loading through <code>ModuleRegistry</code>.</li><li>Native fallback for bytecode imports.</li></ul><p>Out of scope:</p><ul><li>Source module resolver basics.</li><li>Native descriptor model.</li><li>Full debug info format.</li><li>Incremental recompilation.</li></ul><h2 id="ngo-contents" tabindex="-1"><code>.ngo</code> Contents <a class="header-anchor" href="#ngo-contents" aria-label="Permalink to “.ngo Contents”">​</a></h2><p><code>.ngo</code> should contain:</p><ul><li>Implemented: magic/version.</li><li>Implemented: canonical module ID.</li><li>Implemented: compiler ABI version.</li><li>Implemented: source hash or build hash.</li><li>Implemented: export index.</li><li>Implemented: import dependency list.</li><li>Implemented: type metadata needed by type checker for exported symbols.</li><li>Implemented: trait shape metadata, impl metadata, and method evidence.</li><li>Implemented: ORGASM bytecode.</li><li>Optional debug source mapping.</li></ul><h2 id="loader-behavior" tabindex="-1">Loader Behavior <a class="header-anchor" href="#loader-behavior" aria-label="Permalink to “Loader Behavior”">​</a></h2><ul><li>If <code>.ngo</code> is present and compatible, load it directly.</li><li>If <code>.ngo</code> is stale or incompatible and <code>.ng</code> exists, load source and optionally rebuild bytecode.</li><li>If only <code>.ngo</code> exists, type checking relies on embedded type metadata.</li><li>If both source and bytecode are missing, check native registry.</li></ul><p>Current implementation note:</p><ul><li>Implemented: file loader can load <code>.ngo</code> and <code>module.ngo</code> artifacts before source probes when the artifact is compatible.</li><li>Implemented: <code>.ngo</code> deserialization checks magic, format version, ABI version, metadata schema version, module id, and bounded container sizes.</li><li>Implemented: bytecode-only imports restore exported type/trait metadata into <code>ModuleArtifact</code>, so source importers can type check exported function calls and trait-bound code.</li><li>Implemented: stale/source-hash fallback to source when a matching <code>.ng</code> exists.</li><li>Implemented: fallback to source when <code>.ngo</code> is incompatible or an export is missing required type metadata.</li></ul><p>Compatibility checks:</p><ul><li>Module ID must match requested import.</li><li>Bytecode ABI version must match VM/compiler.</li><li>Type metadata schema version must match type checker.</li><li>Imported dependency hashes can be checked later; initial implementation can warn or ignore.</li></ul><h2 id="orgasm-vm-behavior" tabindex="-1">ORGASM VM Behavior <a class="header-anchor" href="#orgasm-vm-behavior" aria-label="Permalink to “ORGASM VM Behavior”">​</a></h2><p>The VM should load imports by module ID rather than only pre-linked <code>BytecodeModule</code> pointers.</p><p>Required behavior:</p><ul><li>Implemented: resolve imported bytecode module through <code>ModuleRegistry</code>, with lazy file loading by module ID.</li><li>Link function imports by exported symbol.</li><li>Implemented: support native import fallback.</li><li>Keep type/trait metadata available for dynamic dispatch and runtime diagnostics.</li></ul><p>CLI direction:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ngi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-ngo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/foo.ngo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/foo.ng</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ngi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run-bytecode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/foo.ngo</span></span></code></pre></div><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li>Implemented: ORGASM can emit a <code>.ngo</code> artifact for a source module.</li><li>Implemented: ORGASM can execute an entry <code>.ngo</code>.</li><li>Implemented: ORGASM can execute an entry <code>.ngo</code> that imports another <code>.ngo</code>.</li><li>Implemented: <code>.ngo</code> and <code>.ng</code> modules expose the same exported symbols to importers.</li><li>Implemented: incompatible ABI/schema versions fail before execution.</li><li>Implemented: native imports from bytecode modules resolve through the native module registry.</li></ul><h2 id="phased-implementation-plan" tabindex="-1">Phased Implementation Plan <a class="header-anchor" href="#phased-implementation-plan" aria-label="Permalink to “Phased Implementation Plan”">​</a></h2><h3 id="phase-1-bytecode-artifact-container" tabindex="-1">Phase 1: Bytecode Artifact Container <a class="header-anchor" href="#phase-1-bytecode-artifact-container" aria-label="Permalink to “Phase 1: Bytecode Artifact Container”">​</a></h3><ul><li>Implemented: binary <code>.ngo</code> read/write for <code>BytecodeModule</code>.</li><li>Implemented: magic, format version, ABI version, module id, imports, exports, strings, constants, functions, types, and variants.</li><li>Implemented: CLI <code>--emit-ngo &lt;path&gt; source.ng</code>.</li><li>Implemented: CLI <code>--run-bytecode module.ngo</code>.</li><li>Implemented: VM lazy loads imported <code>.ngo</code> modules from configured module paths.</li><li>Implemented: tests cover artifact roundtrip and an entry module importing another <code>.ngo</code>.</li></ul><h3 id="phase-2-embedded-typechecker-metadata" tabindex="-1">Phase 2: Embedded Typechecker Metadata <a class="header-anchor" href="#phase-2-embedded-typechecker-metadata" aria-label="Permalink to “Phase 2: Embedded Typechecker Metadata”">​</a></h3><ul><li>Implemented: persist exported type reprs, exported trait shape metadata, and exported impl evidence.</li><li>Implemented: restore exported type and trait metadata into <code>ModuleArtifact</code> for source modules importing bytecode-only modules.</li><li>Implemented: tests cover source type checking against <code>.ngo</code> function and trait metadata.</li><li>Implemented: validate metadata schema version independently from bytecode ABI version.</li></ul><h3 id="phase-3-bytecode-first-loader-policy" tabindex="-1">Phase 3: Bytecode-First Loader Policy <a class="header-anchor" href="#phase-3-bytecode-first-loader-policy" aria-label="Permalink to “Phase 3: Bytecode-First Loader Policy”">​</a></h3><ul><li>Implemented: prefer compatible <code>.ngo</code> over <code>.ng</code> when both exist.</li><li>Implemented: fall back to source when <code>.ngo</code> is stale or incompatible.</li><li>Implemented: source/build hash checks.</li><li>Implemented: fall back to source when <code>.ngo</code> is missing required metadata.</li></ul><h3 id="phase-4-native-and-debug-metadata" tabindex="-1">Phase 4: Native And Debug Metadata <a class="header-anchor" href="#phase-4-native-and-debug-metadata" aria-label="Permalink to “Phase 4: Native And Debug Metadata”">​</a></h3><ul><li>Implemented: persist import dependency records and resolve native fallback through the VM native registry.</li><li>Optional: add debug source mapping.</li><li>Implemented: expose fail-fast diagnostics for invalid bytecode magic, ABI/schema mismatches, module id mismatches, and missing imports.</li></ul>`,41)])])}const u=a(l,[["render",d]]);export{h as __pageData,u as default};
